package com.lolfm.composition;
import java.util.*;
public final class CompositionAggregationPolicy{private static final Map<CompositionAggregationType,double[]>WEIGHTS=Map.of(CompositionAggregationType.PRIMARY_SOURCE,new double[]{.75,.20,.05,0,0},CompositionAggregationType.DUAL_SOURCE,new double[]{.55,.30,.15,0,0},CompositionAggregationType.DISTRIBUTED,new double[]{.40,.25,.15,.10,.10});private static final Map<CompositionCapability,CompositionAggregationType>TYPES=types();private CompositionAggregationPolicy(){}public static CompositionAggregationType type(CompositionCapability c){return TYPES.get(Objects.requireNonNull(c));}public static double weight(CompositionAggregationType t,int rank){if(rank<1||rank>5)throw new IllegalArgumentException();return WEIGHTS.get(t)[rank-1];}public static Map<CompositionCapability,CompositionAggregationType>types(){EnumMap<CompositionCapability,CompositionAggregationType>m=new EnumMap<>(CompositionCapability.class);for(var c:List.of(CompositionCapability.ENGAGE,CompositionCapability.PICK,CompositionCapability.SIEGE,CompositionCapability.SIDE_LANE_PRESSURE,CompositionCapability.BACKLINE_ACCESS))m.put(c,CompositionAggregationType.PRIMARY_SOURCE);for(var c:List.of(CompositionCapability.FOLLOW_UP,CompositionCapability.DISENGAGE,CompositionCapability.FRONTLINE,CompositionCapability.PEEL,CompositionCapability.POKE,CompositionCapability.WAVE_CLEAR,CompositionCapability.ZONE_CONTROL,CompositionCapability.BURST_DAMAGE))m.put(c,CompositionAggregationType.DUAL_SOURCE);for(var c:List.of(CompositionCapability.OBJECTIVE_DAMAGE,CompositionCapability.SUSTAINED_DAMAGE))m.put(c,CompositionAggregationType.DISTRIBUTED);if(m.size()!=15)throw new IllegalStateException();return Map.copyOf(m);}}
